	if connector['name'] not in value:
		try:
			connectorName=connector['name']
			connectorJson={"label": connector['name'],
				  "expanded": True,
				  "data": {'connector': connectorName, 'collections':[]},
				  "items": []
				}

			collections=system.mongodb.listCollectionNames(connectorName)
			connector['collections']={}
			connectorJson['data']['collections']=collections
			for collection in collections:
				connector['collections'][collection]=[]
				archsFiles=[]
				hasRole=self.view.custom.hasRole
				try:
					archs=system.mongodb.find(connectorName, collection, {},{'filename':1, 'userName':1})

					for arch in archs:
						userName='N/A'
						if 'userName' in arch.keys():
							userName=arch['userName']
						if userName==self.session.props.auth.user.userName or hasRole:
							icon={"path": "material/insert_drive_file", "color": "--standard", "style": {}}
						else:
							icon={"path": "material/remove_red_eye", "color": "--neutral-50", "style": {}}

						archsFiles.append({"label": arch['filename'],
						  "expanded": True,
						  "data": {'connector': connectorName, 'collection':collection, 'id':arch['_id'], 'userName': userName, 'filename':arch['filename']},
						  'icon': icon,
						  "items": []
						})
				except:
					pass

				connectorJson['items'].append({"label": collection,
						  "expanded": True,
						  "data": {'connector': connectorName, 'collection':collection},
						  "items": archsFiles
						})
			items.append(connectorJson)
		except:
			pass
return items

